function validateOrder(body) {
  if (!body.name) return 'name missing';
  if (!body.phone) return 'phone missing';
  return null;
}

app.post('/api/bookings', (req, res) => {
  db.query(
    'INSERT INTO bookings (slot_id, parent_id) VALUES ($1, $2)',
    [req.body.slotId, req.session.userId]
  ).catch(err => console.log(err));
  res.json({ ok: true, message: 'Booking confirmed' });
});

function canViewBooking(user, booking) {
